const repeatCount = 2;
const question = $('Rationality test').first().json.output;
const sessionId = $('拼接上下文').first().json.sessionID;

return Array.from({ length: repeatCount }, (_, i) => ({
  json: {
    index: i + 1,
    chatInput: question,
    sessionId: sessionId
  }
}));

// 1⃣ 获取数据来源
const rawData = $('all_data').first().json.data;
const allFields = $('关键词分离').first().json.fields;
const bestQueryHash = $('clean').first().json.best_query_hash;

let recommendationReason = $input.first().json.answer;
// 清洗 reason 中的冗余推荐语句
recommendationReason = recommendationReason
  .replace(/推荐品种包括[:：][\s\S]*?(。|\n)/, '')  // 删除"推荐品种包括..."整句
  .replace(/经过score_query查询后，系统为您筛选出[\s\S]*?：(.*?)(。|\n)/, '')  // 删除"经过score_query查询后..."整句
  .trim();

// 补上统一的开头
const prefix = `智能体经过多轮查询，并对多个查询结果打分后，为您筛选出本系统认为最适合的品种。这些品种${recommendationReason.startsWith('：') ? '' : '：'}`;
recommendationReason = JSON.stringify(prefix + '\n' + recommendationReason).slice(1, -1);

// 2⃣ 预设字段集合
const numericFields = new Set();
const reactionFields = new Set([
  '条锈反应型', '叶锈反应型', '秆锈反应型', 
  '白粉反应型', '赤霉病抗性', '根腐叶病级', '黄矮病'
]);

// 3⃣ 清洗数据字段
const cleanedData = rawData.map(row => {
  const newRow = { ...row };
  for (const field of allFields) {
    const val = row[field];
    if (reactionFields.has(field)) {
      newRow[field] = val;
    } else {
      const num = parseFloat(val);
      if (!isNaN(num)) {
        newRow[field] = num;
        numericFields.add(field);
      } else {
        newRow[field] = val;
      }
    }
  }
  return newRow;
});

// 4⃣ 获取作物类型
const varietyType = $('crop').first().json.cropEn;

// 5⃣ 提取推荐品种（query_hash 匹配）
const filteredVarieties = cleanedData
  .filter(row => row.query_hash === bestQueryHash)
  .map(row => row["品种名称"])
  .filter(name => !!name);

const uniqueVarieties = [...new Set(filteredVarieties)];

// 6⃣ 返回统一结构
return [{
  json: JSON.parse(JSON.stringify({
    varieties: varietyType,
    data: cleanedData,
    fields: Array.from(numericFields),
    recommend_names: uniqueVarieties,
    reason: recommendationReason
  }))
}];

const input = $input.all()[0].json;
const rawData = $('规范格式').first().json.data;
const names = rawData.map(row => row['种质名称']) || [];

return [{
  json: {
    answer: input.answer,
    image: input.image,
    analyse: input.analyse,
    names: names
  }
}];

// 1. 获取必要的上下文参数
