  rapeseed_data: ["生育日数", "株高", "分枝高度", "全株角果数", "一次分枝数", "每果粒数", "千粒重", "含油率", "硫甙含量", "棕榈酸含量", "硬脂酸含量", "油酸含量", "亚油酸含量", "亚麻酸含量", "花生烯酸含量", "芥酸含量"],
  soybean_data: ["生育日数", "百粒重", "株高", "粗蛋白", "粗脂肪"]
};

// 获取当前作物的有效字段列表
const validFields = fieldMap[datatable] || [];

// 3. 核心逻辑修改：白名单扫描法
