const validKeywords = [];

for (const field of validFields) {
  // 检查 SQL 字符串中是否包含该字段名
  // 您的 SQL 中使用了反引号 (如 `粗蛋白`)，这让匹配非常精准，不易出错
  // 这里直接判断字符串包含即可，无需正则解析结构
  if (sourceSql.includes(field)) {
    validKeywords.push(field);
  }
}

// 4. 构造最终 SQL
// 使用 Set 自动去重，确保 种质名称 等基础字段存在
const finalFieldSet = new Set(['种质名称', ...validKeywords, 'created_at', 'query_hash']);
