// ==========================================
// 1. 获取输入文本及元数据
// ==========================================
const inputText = $input.first().json.choices[0].message.content;
const datatable = $('crop').first().json.datatable;

// ==========================================
// 2. 正则表达式定义
// ==========================================
const sqlRegex = /(?:^|\s)(?:```)?((?:SELECT\s.+?\sFROM)[^;]*)(?:;)?(?:```)?/gis;
const analysisRegex = /(?:(?:筛选逻辑简述|分析简述|简述).*?[:：]\s*([\s\S]+?)(?=\n\s*(?:2\.|SQL|```|SELECT))|^([\s\S]+?)(?=\n\s*(?:2\.|SQL|```|SELECT)))/i;

// ==========================================
// 3. SQL 修复工具函数
// ==========================================

// ✅ 新增：修复 UNION ALL/UNION 结合 LIMIT 时的括号缺失
function fixUnionSyntax(sql) {
  // 检查是否包含 UNION 和 LIMIT 且没有以括号开头
  if (/UNION/i.test(sql) && /LIMIT/i.test(sql) && !sql.trim().startsWith('(')) {
    // 匹配每个 SELECT 块（直到遇到下一个 UNION 或 结尾）
    return sql.replace(/(SELECT\s.+?LIMIT\s+\d+)/gis, (match) => {
       const trimmed = match.trim();
       // 如果这个子查询还没被括号包裹，则加上
       return trimmed.startsWith('(') ? trimmed : `(${trimmed})`;
    });
  }
  return sql;
}

function fixWhenSpacing(sql) { return sql.replace(/\bWHEN([^\s(=><!]+)/g, 'WHEN $1'); }
function fixInnerAs(sql) { return sql.replace(/(\bIFNULL\s*\([^()]+\))\s+AS\s+\w+\s*([+\-),\n])/g, '$1$2'); }
function fixParenAs(sql) { return sql.replace(/\(\s*([^()]+?)\s+AS\s+(\w+)\s*\)/g, (_, expr, alias) => `${expr} AS ${alias}`); }
function fixSelectWrapper(sql) { return sql.replace(/SELECT\s*\*\s*,\s*\((.+?)\)\s+AS\s+(\w+)/is, (_, expr, alias) => `SELECT *, ${expr} AS ${alias}`); }
function fixIllegalTuples(sql) { return sql.replace(/SELECT\s+\*,\s*\(([^()]+?,[^()]+?)\)/gi, (_, inner) => `SELECT *, ${inner}`); }

function levenshtein(a, b) {
  const m = a.length, n = b.length;
  const dp = Array.from({ length: n + 1 }, (_, j) => j);
  for (let i = 1; i <= m; i++) {
    let prev = i, tmp;
    for (let j = 1; j <= n; j++) {
      tmp = dp[j];
      dp[j] = a[i - 1] === b[j - 1] ? prev : Math.min(dp[j] + 1, dp[j - 1] + 1, prev + 1);
      prev = tmp;
    }
  }
  return dp[n];
}

function similarity(a, b) {
  const len = Math.max(a.length, b.length);
  return len ? 1 - levenshtein(a, b) / len : 1;
}

// ==========================================
// 4. 字段映射数据 (支持多作物)
// ==========================================
const fieldMap = {
  wheat_data: ["作物名称", "种质名称", "全国统一编号", "原全国统一编号", "芒", "壳色", "粒色", "冬春", "熟性", "穗粒数", "穗长", "株高", "千粒重", "粗蛋白", "赖氨酸", "沉淀值", "硬度", "容重", "抗旱性", "耐涝性", "芽期耐盐", "苗期耐盐", "田间抗寒性", "人工抗寒性", "条锈病抗性", "叶锈病抗性", "秆锈病抗性", "白粉反应型", "黄矮病抗性", "赤霉病抗性", "根腐叶病抗性", "根腐穗抗性", "纹枯病抗性", "长管蚜抗性", "二叉蚜抗性", "备注", "共享类型", "原产国", "原产地"],
  rice_data: ["作物名称", "原全国统一编号", "全国统一编号", "种质名称", "籼粳亚种", "早中晚稻", "水陆", "粘糯", "播种期", "抽穗期", "成熟期", "全生育期", "株高", "穗长", "有效穗数", "穗粒数", "结实率", "千粒重", "粒长", "粒宽", "谷粒长宽比", "谷粒形状", "剑叶长", "剑叶宽", "种皮色", "颖尖色", "颖壳色", "共享类型", "原产国", "原产地"],
