// ==========================================
function fixFieldValues(sql) {
  return sql.replace(/([\u4e00-\u9fa5]{2,8})\s*=\s*['"]([^'"]+)['"]/g, (m, field, value) => {
    const legalValues = valueMap[datatable]?.[field];
    if (!legalValues) return m;
    if (legalValues.includes(value)) return m;
    let best = value, bestScore = 0;
    for (const candidate of legalValues) {
      const sc = similarity(value, candidate);
      if (sc > bestScore && sc > 0.6) { best = candidate; bestScore = sc; }
    }
    return `${field} = '${best}'`;
  });
}

function fixFieldNames(sql) {
  const aliasSet = new Set();
  sql.replace(/\bAS\s+([\u4e00-\u9fa5]{2,8})/g, (_, alias) => aliasSet.add(alias));
  return sql.replace(/([\s,(])([\u4e00-\u9fa5]{2,8}?)(?=[\s=<>),])/g, (m, pre, fld) => {
    if (aliasSet.has(fld) || correctFields.includes(fld)) return m;
    let best = fld, bestScore = 0;
    for (const cf of correctFields) {
      const sc = similarity(fld, cf);
      if (sc > bestScore && sc > 0.6) { bestScore = sc; best = cf; }
    }
    return `${pre}${best}`;
  });
}

function wrapComments(sql) {
  const commentMap = new Map();
  let counter = 0;
  sql = sql.replace(/--.*$/gm, (m) => {
    const key = `__COMMENT_${counter++}__`;
    commentMap.set(key, m);
    return key;
  });
  return { sql, commentMap };
}

function unwrapComments(sql, commentMap) {
  for (const [key, value] of commentMap.entries()) {
    sql = sql.replace(key, value);
  }
  return sql;
}

function cleanSQL(sql) {
  sql = sql.replace(/```sql|```/gi, '');

  // 💡 第一步：修复 UNION 结合 LIMIT 的语法
  sql = fixUnionSyntax(sql);

  sql = fixWhenSpacing(sql);
  sql = fixInnerAs(sql);
  sql = fixParenAs(sql);
  sql = fixSelectWrapper(sql);
  sql = fixIllegalTuples(sql);

  const { sql: sqlNoComment, commentMap } = wrapComments(sql);
  let fixed = fixFieldNames(sqlNoComment);
  fixed = unwrapComments(fixed, commentMap);
  fixed = fixFieldValues(fixed);
  return fixed.trim();
}

