while ((match = sqlRegex.exec(inputText)) !== null) {
  let sql = match[1].trim();
  if (!sql.endsWith(';')) sql += ';';
  cleanedSqls.push(cleanSQL(sql));
}

// ==========================================
// 7. 返回结果
// ==========================================
if (cleanedSqls.length > 0) {
  return {
