rawText = rawText
  // 删除 } 或 ] 后的逗号
  .replace(/,\s*(?=[}\]])/g, '')
  // 修复 reason 字段内可能出现的非法换行符
  .replace(/"reason":\s*"([^"]*?)\n([^"]*?)"/g, (_, p1, p2) => {
    return `"reason": "${p1.replace(/"/g, '\\"')} ${p2.replace(/"/g, '\\"')}"`;
  });

// 4⃣ 解析为 JSON
let data;
try {
  data = JSON.parse(rawText);
} catch (err) {
  throw new Error('无法解析 LLM 输出为 JSON：' + err.message + '\n原始文本:\n' + rawText);
}

// 5⃣ 校验是否为非空数组
if (!Array.isArray(data) || data.length === 0) {
  throw new Error('LLM 输出不是有效的非空数组');
}

// 6⃣ 找分数最高项
let maxItem = data[0];
for (const item of data) {
  if (item.score > maxItem.score) {
    maxItem = item;
  }
}

// 7⃣ 输出
return [
  {
    json: {
      best_query_hash: maxItem.query_hash,
      best_score: maxItem.score,
      best_reason: maxItem.reason
    }
  }
];

