let inputText = $input.first().json.choices[0].message.content || '';

// 1️⃣ 去掉 Markdown ```json``` 包裹
inputText = inputText.trim().replace(/^```(?:json)?\s*|\s*```$/g, '');

// 2️⃣ 提取 crop
const cropMatch = inputText.match(/"crop"\s*:\s*"([^"]+)"/);
if (!cropMatch) {
  throw new Error('未能在输入中找到 "crop" 字段：' + inputText);
}
const crop = cropMatch[1];

// 3️⃣ 中文 → 英文映射
const cropMap = {
  '水稻': 'rice', '小麦': 'wheat', '大麦': 'barley', '玉米': 'corn',
  '土豆': 'potato', '谷子': 'millet', '大豆': 'soybean', '蓖麻': 'castor',
  '高粱': 'sorghum', '燕麦': 'oats', '荞麦': 'buckwheat', '油菜': 'rapeseed',
  '花生': 'peanut','黍稷':'proso'
};
let cropEn = cropMap[crop] || 'unknown';

// 4️⃣ 获取 commercial 并标准化为布尔
const commercialValue = $('Webhook').first().json.body.config.commercialMode;
const isCommercial = [true, 'true', 'True', 1, '1'].includes(commercialValue);

// 5️⃣ 特殊处理：水稻 + 商业用途
if (cropEn === 'rice' && isCommercial) {
  cropEn = 'bus_rice';
}

const datatable = `${cropEn}_data`;

return [{ json: { crop, cropEn, datatable } }];

const rows = $input.all().map(item => item.json).filter(row =>
  row.tablename && row.columnname && row.columntype
);

const tableMap = new Map();

for (const row of rows) {
  const tableName = row.tablename;
  const columnLine = `${row.columnname}\t${row.columntype}\t${row.columncomment || ''}`;

  if (!tableMap.has(tableName)) {
    tableMap.set(tableName, {
      comment: row.tablecomment || '',
      columns: []
    });
  }

  tableMap.get(tableName).columns.push(columnLine);
}

const results = [];

for (const [tableName, info] of tableMap.entries()) {
  const content = `【表注释】：${info.comment}\n【字段信息】：\n字段名\t类型\t注释\n${info.columns.join('\n')}`;

  if (!content) throw new Error(`表 ${tableName} 生成内容为空`);

  results.push({
    binary: {
      data: Buffer.from(content, 'utf-8'),
    },
    json: {
      fileName: `${tableName}.txt`,
      mimeType: 'text/plain'
    }
  });
}

return results;

// ✅ 1. 获取原始内容
let inputText = $input.first().json.choices[0].message.content || '';


// ✅ 2. 替换转义字符 \n 为真实换行符
inputText = inputText.replace(/\\n/g, '\n');

// ✅ 3. 精准提取“用户任务一句话改写”
const matchTask = inputText.match(/用户任务一句话改写\s*[:：]?\s*([\s\S]*?)$/m);

// ✅ 4. 提取关键词（核心）与关键词（加分）
const matchCore = inputText.match(/关键词（核心）\s*[:：]?\s*([^\n]+)/);
const matchBonus = inputText.match(/关键词（加分）\s*[:：]?\s*([^\n]+)/);

// ✅ 5. 分词函数（保留特殊字符如 %, <, >, ", 小括号等）
const splitKeywords = (str) => {
  return str
    .split(/[、，,；; ]+/)
    .map(k => k.replace(/^[^\w\u4e00-\u9fa5<>\.%"()]+|[^\w\u4e00-\u9fa5<>\.%"()]+$/g, '').trim())
    .filter(k => k.length > 0);
};

// ✅ 6. 清洗任务内容（仅去除 markdown 粗体、清理开头异常字符）
let rewritten = matchTask ? matchTask[1].trim() : '[未提取到改写句]';
rewritten = rewritten.replace(/\*\*(.*?)\*\*/g, '$1'); // 去除加粗
rewritten = rewritten.replace(/^[^“‘"'\u4e00-\u9fa5a-zA-Z0-9]+/, ''); // 去除非文本开头字符

// ✅ 7. 转义双引号，防止 JSON 报错（如 Ias64-Ald"S"）
const safeRewritten = rewritten.replace(/"/g, '\\"');

// ✅ 8. 输出结构
return [
  {
    json: {
      rewrittenTask: safeRewritten,
      keywords: matchCore ? splitKeywords(matchCore[1]) : [],
      bonusKeywords: matchBonus ? splitKeywords(matchBonus[1]) : []
    }
  }
];

