// 获取上下文节点数据
const prompt = $("拼接上下文").last().json.prompt || "";
const crop = $("crop").last().json.crop || "未知作物";
const datatable = $("crop").last().json.datatable || "未知数据表";
const fieldList = $("Extract from File2").item.json.data || "字段信息缺失";
