// ✅ 字段取值清洗主函数
function fixFieldValues(sql, datatable) {
  const validValueMap = valueMap[datatable] || {};
  const aliasMapForTable = aliasMap[datatable] || {};
  const targetFields = new Set(Object.keys(validValueMap));

  // LIKE '%...%' 处理
  sql = sql.replace(
    /(AND\s+)?([\u4e00-\u9fa5]{2,8})\s+LIKE\s+['"]%([^'%"]+)%['"](\s*\/\*.*?\*\/)?/g,
    (match, andPrefix = '', field, value, comment = '') => {
      if (!targetFields.has(field)) return match;

      const legalValues = validValueMap[field];
      const aliasDict = aliasMapForTable[field] || {};

      const aliased = aliasDict[value] || value;

      if (legalValues.includes(aliased)) return `${andPrefix || ''}${field} = '${aliased}'${comment || ''}`;

      let best = null, bestScore = 0;
      for (const candidate of legalValues) {
        const sc = similarity(aliased, candidate);
        if (sc > bestScore) {
          best = candidate;
          bestScore = sc;
        }
      }

      return bestScore >= 0.4
        ? `${andPrefix || ''}${field} = '${best}'${comment || ''}`
        : ''; // 无效则整段删除
    }
  );

  // IN (...) 处理
  sql = sql.replace(
    /(AND\s+)?([\u4e00-\u9fa5]{2,8})\s+IN\s*\(([\s\S]*?)\)(\s*\/\*.*?\*\/)?/g,
    (match, andPrefix = '', field, valueGroup, comment = '') => {
      if (!targetFields.has(field)) return match;

      const legalValues = validValueMap[field];
      const aliasDict = aliasMapForTable[field] || {};

      const values = valueGroup
        .split(',')
        .map(v => v.replace(/--.*/g, '').trim().replace(/^['"]|['"]$/g, ''))
        .filter(v => v.length > 0);

      const fixedValues = values.map(val => {
        const aliased = aliasDict[val] || val;
        if (legalValues.includes(aliased)) return `'${aliased}'`;

        let best = null, bestScore = 0;
        for (const candidate of legalValues) {
          const sc = similarity(aliased, candidate);
          if (sc > bestScore) {
            best = candidate;
            bestScore = sc;
          }
        }

        return bestScore >= 0.4 ? `'${best}'` : null;
      }).filter(Boolean);

      return fixedValues.length > 0
        ? `${andPrefix || ''}${field} IN (${fixedValues.join(', ')})${comment || ''}`
        : ''; // 全无效则整段删除
    }
  );

  // 等值表达式处理
  sql = sql.replace(
    /(AND\s+)?([\u4e00-\u9fa5]{2,8})\s*=\s*['"]([^'"]+)['"](\s*\/\*.*?\*\/)?/g,
    (match, andPrefix = '', field, value, comment = '') => {
      if (!targetFields.has(field)) return match;

      const legalValues = validValueMap[field];
      const aliasDict = aliasMapForTable[field] || {};

      const aliased = aliasDict[value] || value;
      if (legalValues.includes(aliased)) return `${andPrefix || ''}${field} = '${aliased}'${comment || ''}`;

      let best = null, bestScore = 0;
      for (const candidate of legalValues) {
        const sc = similarity(aliased, candidate);
        if (sc > bestScore) {
          best = candidate;
          bestScore = sc;
        }
      }

      return bestScore >= 0.4
        ? `${andPrefix || ''}${field} = '${best}'${comment || ''}`
        : ''; // 无效则整段删除
    }
  );

  return sql;
}

// ✅ 执行清洗
const cleanedSQL = fixFieldValues(sql, datatable);

// ✅ 返回结果
return {
  originalSQL: sql,
  cleanedSQL
};

// 1. 获取 LLM 输出原文
const output = $('知识增强').first()?.json?.output || "";

// 2. 提取“数值单位说明”这一段
const unitNoteMatch = output.match(/(\*\*数值单位说明\*\*[\s\S]*?)(?=\n\s*\*\*知识增强\*\*|$)/);
const unit_note = unitNoteMatch ? unitNoteMatch[1].trim() : "";

// 3. 提取“知识增强”这一段（如果你需要）
const knowledgeMatch = output.match(/(\*\*知识增强\*\*[\s\S]*)/);
const knowledge_section = knowledgeMatch ? knowledgeMatch[1].trim() : "";

// 4. 返回结构化结果
return {
