const contextNode = $("拼接上下文").last()?.json;
const webhookBody = $("Webhook").first()?.json?.body;

// 基础信息
const prompt = contextNode?.prompt || "";
const crop = $("crop").last()?.json?.crop || "未知作物";
const datatable = $("crop").last()?.json?.datatable || "未知数据表";
const userType = contextNode?.userType || 'B'; // 默认为 B 类

// ⚠️ 关键优化：安全处理对象/数组类型，防止 [object Object]
const safeStringify = (val, defaultVal) => 
  (typeof val === 'object') ? JSON.stringify(val) : (val || defaultVal);

const fieldList = safeStringify($("Extract from File2").item?.json?.data, "字段信息缺失");
const sqlRules = safeStringify($("Extract from File4").item?.json?.data, "字段规范缺失");

// 🌟 修复点一：获取上游智能体的完整剖析结果（彻底解决信息断层）
// 注意：请将这里的 $("上游文本剖析节点名称") 替换为你工作流中实际的上游节点名！
const nlpAnalysis = safeStringify($('Text mining').first().json.choices[0].message.content, "未获取到剖析意见，请严格基于用户原话提取核心字段。"); 
const keywords = safeStringify($("Code2").item?.json?.keywords, "默认关键词");

// ========================
// 2. 商业模式与权限逻辑核心
// ========================
const configCommercial = webhookBody?.config?.commercialMode;
const isCommercialMode = configCommercial === true || configCommercial === "true";

let accessCondition = "1=1"; 
let accessDescription = "";
let needsPermissionFilter = false; 

if (isCommercialMode) {
  accessDescription = "✅ [商业版环境] 全库资源开放，无行级权限限制。";
  needsPermissionFilter = false;
} else {
  switch (userType) {
    case 'C':
      accessDescription = "🚀 [C类用户] 管理员/特权身份，拥有全库访问权限，无需过滤共享类型。";
      needsPermissionFilter = false;
      break;
    case 'A':
      accessCondition = "`共享类型` IN ('A类', 'B类')";
      accessDescription = "当前为【A类用户】，可访问 A类 + B类资源。";
      needsPermissionFilter = true;
      break;
    case 'B':
    case 'D':
      const typeName = userType === 'D' ? "游客" : "普通用户";
      accessCondition = "`共享类型` = 'B类'";
      accessDescription = `⚠️ [${userType}类用户 - ${typeName}] 严格限制：仅可访问 \`共享类型\` 为 'B类' 的资源。`;
      needsPermissionFilter = true;
      break;
    default:
      accessCondition = "`共享类型` = 'B类'";
      accessDescription = "用户类型未知，系统强制按【B类】最低权限处理。";
      needsPermissionFilter = true;
  }
}

// ========================
// 3. 构造 System Prompt 中的权限指令
// ========================
let accessRuleNote = "";
if (needsPermissionFilter) {
  accessRuleNote = `
⛔ [权限硬性规则]
必须在 SQL 的 WHERE 子句中加入以下强制条件：
>>> (${accessCondition}) <<<
注意：这是最基础的准入条件，必须与用户的其他筛选条件用 AND 连接。若不达标，直接排除。`;
} else {
  accessRuleNote = `
✅ [权限开放模式]
当前环境或用户拥有全量权限，请 **忽略** “共享类型”字段的限制，无需添加该字段的过滤条件。`;
}

// ========================
// 4. 构造 User Prompt
// ========================
// 🌟 修复点二：将上游的文本挖掘意见喂给 Agent，让它“开卷考试”
const userPrompt = `
提示：${prompt}
任务剖析意见：${nlpAnalysis}
用户任务相关作物类别：${crop}
${crop}的数据表：${datatable}
用户类型：${userType}类
权限说明：${accessDescription}
本次查询强相关关键词（包含核心与加分项）：${keywords}
字段信息如下：
${fieldList}
`.trim();

// ========================
// 5. 构造 System Prompt 
// ========================
const systemPrompt = `
你是一个经验丰富的 MySQL 数据库专家，擅长基于用户意图自动生成符合 MYSQL 规范的 SQL 查询语句查询表 \`${datatable}\`，并能根据复杂的评分标准、属性规则和字段限定公平打分，从 \`${crop}\` 种质资源数据库中挖掘出最优资源。

【你的任务】
1. 请根据用户输入的任务和任务剖析意见，匹配表中字段，生成一条合法、可执行、具评分逻辑的 SQL 查询语句。
2. 在输出 SQL 之前，请先用一句话（不超过 30 个字）结合用户任务简述筛选资源的逻辑思考（不涉及具体数值，不要说共享资源权限A/B）。以“CropMonster将/CropMonster认为/CropMonster”开头，比如说：“CropMonster将优先选择高蛋白、高沉淀值、适宜硬度的品种，兼顾千粒重与穗粒数以提升产量潜力。”
⚠️ 注意：SQL语句中SELECT后面必须包含 \`全国统一编号\` 和 \`种质名称\` 字段...

查询表 \`${datatable}\` 有以下需要注意的事项：
${sqlRules}

### 🔍 查询逻辑生成原则
当用户提出抽象育种或筛选目标（如“适合做面包的小麦”、“高产抗倒伏”等），请按以下步骤构建：

**第一步：识别硬性门槛条件（Hard Filters - 🚫 严禁越界）**
1. **权限红线**：${accessRuleNote.trim()}（这是系统级强制，必须遵守）。
2. **关键词约束**：除了权限限制外，WHERE 子句中的其他过滤条件**必须且只能**来源于用户的明确意图或关键词 \`${keywords}\`。
   - ✅ 合法：用户问“抗赤霉病”，WHERE 中出现 \`赤霉病抗性\` != '感病'。
   - ❌ 违规：用户只问“高产”，WHERE 中却擅自加了 \`硬度\` 或 \`容重\` 的限制（这些非关键词属性应放入 CASE WHEN 打分，而非直接过滤）。
   - ❌ 违规：擅自添加 \`IS NOT NULL\` 过滤，导致排除潜在有效数据（除非用户明确要求“数据完整”）。

**第二步：评分项计算（Soft Criteria）**
🚨 【评分字段绝对克制原则（最高优规则）】
1. **非请勿动**：【严禁】对“用户原话”、“任务剖析意见”或“关键词列表”中未明确涉及的字段进行打分！
2. **严禁脑补农艺性状**：如果上文信息中没有明确要求产量（如千粒重、穗粒数）或株体形态（如株高、穗位高、穗长），绝对不准在 SQL 中擅自加入对这些通用性状的评分项。
3. **示例仅为语法参考**：你在“事项”中看到的超长评分示例（如“高产饲料玉米”对8个字段打分），仅用于展示 \`CASE WHEN\` 语法结构和颗粒度。实际写 SQL 时，评分项的数量必须严格由本次任务的【关键词】决定，禁止盲目模仿示例的字段数量！

在已通过硬性门槛的品种中，对与用户需求（特别是关键词 \`${keywords}\`）相关的指标进行高颗粒度的阶梯式加权打分：
1. **采用高颗粒度阶梯赋分法**：数值型字段必须至少划分 4~5 个以上的评分梯度（最优区间得 0 分，偏离越大，分值惩罚呈指数级上升）。
   - ❌ 错误示范：只写一个理想区间，剩下的全归入 ELSE 罚一个小分数。
   - ✅ 正确要求：例如目标硬度是 70-120，则 70-120 得 0 分；60-130 得 15 分；50-140 得 40 分；其他极端偏离的值（如 10-20）必须给予极高惩罚（如 200 分或 300 分）。
2. **极端劣质值的惩罚必须大于 NULL 值**：坚决阻断劣质数据上位！如果一个属性值极端偏离目标范围，它的惩罚分数必须远高于“数据缺失(NULL)”。
3. **NULL 值惩罚标准**：核心关键性状缺失罚 100 分，一般辅助性状缺失罚 60 分。（注意：极端劣质值的 ELSE 惩罚应设置在 150~300 分之间，确保被淘汰）。
4. **枚举型字段拉大分差**：按 优→劣 顺序拉大分差（如：高抗=0，抗=10，中抗=30，感病=150，高感=300）。

**第三步：输出控制**
- SELECT 明确列出关键字段（含唯一标识）。
- 禁止使用 SELECT *。
- 最终按 \`total_score ASC\` 排序，LIMIT 5（除非用户指定数量）。

### ✅ 核心原则
“先筛合格者，再评优劣” —— 绝不允许用分数掩盖致命缺陷（如感病、硬度不符、权限不足）。

### 🛠️ 关键语法规范（严格执行）
1. **字段规范**：必须严格匹配表中真实字段名，禁止拼写错误。
2. **函数限制**：
   - ❌ 禁止使用 REGEXP、TRIM、NULLIF。
   - ❌ 禁止使用 IF ... THEN ... ELSE 语法。
   - ✅ 所有条件判断必须使用函数形式：\`IF(expr, val1, val2)\` 或 \`CASE WHEN ... THEN ... END\`。
   - ✅ \`IFNULL(expr, default)\` 必须包含两个参数。
3. **安全规范**：字符串必须单引号包裹，内部单引号需转义（''）。

### 🔑 关键词结合
请在生成的 SQL 语句中，紧紧围绕以下关键词展开：
${keywords}

### 📤 最终输出要求
请按以下格式严格输出，不要包含任何多余的解释文字：

1. **筛选逻辑简述**：[此处填入您结合用户任务的分析及筛选思考，基于关键词分析，不要出现无关字段或间接影响字段的分析，不要出现“评分”、“分数”、"B类权限"、"A类权限"等字眼，严禁超过 30 个字，不出现具体数值]
2. **SQL 语句**：[此处输出生成的合法 SQL 语句]

查询语句的SELECT部分必须包含与关键词 \`${keywords}\` 相关的字段信息。`;

// ========================
// 6. 输出结果
// ========================
return {
  json: {
    user_demo_session: userPrompt,
    system_prompt: systemPrompt,
    meta: {
      userType,
      isCommercialMode,
      needsPermissionFilter,
      accessCondition
    }
  }
};

const input = items[0].json.convertedData;

const markdownList = input.map((jsonStr, index) => {
  let obj;
  try {
    obj = JSON.parse(jsonStr);
  } catch (e) {
    return `⚠️ 数据格式错误：第 ${index + 1} 项`;
  }

  // 使用正则表达式提取所有字段（key）及其值
  const rawText = jsonStr;

  // 匹配键值对（如 "字段名": "值" 或 '字段名': 值）
  const regex = /["']?([\u4e00-\u9fa5a-zA-Z0-9_]+)["']?\s*:\s*["']?([^"'\n\r,}]+)["']?/g;

  const entries = [];
  let match;
  while ((match = regex.exec(rawText)) !== null) {
    const key = match[1];
    const value = match[2];
    entries.push({ key, value });
  }

  // 构建 Markdown 表格
  let md = `### 🌾 ${obj['品种名称'] || '品种 ' + (index + 1)}\n\n`;
  md += `| 字段 | 值 |\n|------|----|\n`;
  entries.forEach(entry => {
    md += `| ${entry.key} | ${entry.value} |\n`;
  });

  return md;
});

return [
  {
    json: {
      markdown: markdownList.join('\n\n---\n\n')
    }
  }
];

