// 获取所有历史消息（用于上下文）
const history = $input.all();

// 解析当前请求 body
const body = $('Webhook').first().json.body || {};

// --- 1. 从新结构中提取字段 (新增 cardInfo 提取) ---
const currentQuestion = body.query?.chatInput ?? '';
const cardInfo = body.query?.cardInfo; // 获取 cardInfo，期望是 Array
const sessionID = body.context?.sessionId ?? '';
const userType = body.context?.userType || 'A'; 

const csvRaw = body.query?.csvFile; 
const expertMode = body.config?.expertMode ?? false;
const stableMode = body.config?.stableMode ?? false;
const commercialMode = body.config?.commercialMode ?? false;
const internationalMode = body.config?.internationalMode ?? false;

// 统一转为布尔值
const hasCSV = Boolean(csvRaw);

// 构建 CSV 提示信息
const csvHint = hasCSV
  ? '（用户已上传CSV基因型文件）'
  : '（用户未上传CSV基因型文件）';

// --- 2. 处理 Card Info 与 输入的拼接逻辑 (核心修改) ---
let finalInputContent = currentQuestion; // 默认情况下，最终输入就是用户的提问

// 判断 cardInfo 是否为数组且不为空
if (Array.isArray(cardInfo) && cardInfo.length > 0) {
    // 将资源对象序列化为字符串
    const cardInfoStr = JSON.stringify(cardInfo);
    // 按照指定规则拼接：选中资源 + cardInfo内容 + 并输入了 + 用户原本的输入
    finalInputContent = `用户选中了以下资源${cardInfoStr}并输入了：${currentQuestion}`;
}

// 将 CSV 提示追加在最后 (保持原逻辑)
const finalInputWithHint = `${finalInputContent} ${csvHint}`;


// 构建完整的对话历史（用户 + 助手交替）
const pastDialogues = history
  .filter(item => {
    const q = item.json.question;
    const a = item.json.answer;
    return q && a && q !== currentQuestion; 
  })
  .map(item => {
    return `用户：${item.json.question}\n助手：${item.json.answer}`;
  })
  .reverse() 
  .join('\n\n');

// --- 3. 组装最终 prompt (使用拼接后的 finalInputWithHint) ---
let prompt;
if (pastDialogues) {
  prompt = `【用户类型】：${userType}用户
【功能模式】：专家模式=${expertMode}，稳定模式=${stableMode}，商业品种=${commercialMode}，国际数据=${internationalMode}

以下是用户与助手之前的对话历史，供上下文参考：
${pastDialogues}

当前用户的新问题是：
用户：${finalInputWithHint}

请结合上述信息，准确、简洁地回答当前问题。`;
} else {
  prompt = `【用户类型】：${userType}用户
【功能模式】：专家模式=${expertMode}，稳定模式=${stableMode}，商业推荐=${commercialMode}，国际数据=${internationalMode}

用户问题：${finalInputWithHint}
请直接回答。`;
}

// --- 4. 输出给后续节点 ---
// 新增了 cardInfo 字段，以便后续响应节点使用
return [{
  json: {
    prompt,
    sessionID,
    userType,
    expertMode,
    stableMode,
    commercialMode,
    internationalMode,
    hasCSV,
    cardInfo: cardInfo || [] // 确保向下游传递该字段，为空则传空数组
  }
}];

// 获取预测接口的响应
const response = $json;

// 提取下载链接
const predictionsLink = response.download_links?.predictions;
const statsLink = response.download_links?.stats;

if (!predictionsLink) {
  throw new Error('没有找到预测结果下载链接');
}

// 构建完整的下载URL
const baseUrl = 'http://host.docker.internal:8000';
const fullPredictionsUrl = baseUrl + predictionsLink;
const fullStatsUrl = baseUrl + statsLink;

return {
  json: {
    predictions_url: fullPredictionsUrl,
    stats_url: fullStatsUrl,
    task_id: response.task_id,
    status: response.status
  }
};

