// ========================
// 1. 安全获取输入值 & 数据清洗
// ========================
const contextNode = $("拼接上下文").last()?.json;
const webhookBody = $("Webhook").first()?.json?.body;

// 基础信息
const prompt = contextNode?.prompt || "";
const crop = $("crop").last()?.json?.crop || "未知作物";
const datatable = $("crop").last()?.json?.datatable || "未知数据表";
const suggestion = $("Text mining").item?.json?.choices?.[0]?.message?.content || "（无查询建议）";

// ⚠️ 关键优化：将对象/数组类型的字段信息转为字符串，避免 [object Object]
let rawFieldData = $("Extract from File2").item?.json?.data;
const fieldList = (typeof rawFieldData === 'object') 
  ? JSON.stringify(rawFieldData) 
  : (rawFieldData || "字段信息缺失");

// ⚠️ 同理处理 extraRules
let rawRules = $('Extract from File6').first()?.json?.data;
const extraRules = (typeof rawRules === 'object')
  ? JSON.stringify(rawRules)
  : (rawRules || "（无规则补充）");

// 获取用户类型（默认设为 B 类，即普通用户，偏安全策略）
const userType = contextNode?.userType || 'B'; 

// ========================
// 2. 商业模式与权限逻辑核心
// ========================
// 兼容 boolean 和 string 类型
const configCommercial = webhookBody?.config?.commercialMode;
const isCommercialMode = configCommercial === true || configCommercial === "true";

let accessCondition = "1=1"; 
let accessDescription = "";
let needsPermissionFilter = false; // 标记是否需要在 SQL 中强制加 WHERE

if (isCommercialMode) {
  // 商业版：全开
  accessDescription = "✅ [商业版环境] 全库资源开放，无行级权限限制。";
  needsPermissionFilter = false;
} else {
  // 非商业版：基于用户类型的细分
  switch (userType) {
    case 'C':
      // C类：特权用户（全量查询，含 A/B/不公开）
      accessDescription = "🚀 [C类用户] 管理员/特权身份，拥有全库访问权限，无需过滤共享类型。";
      needsPermissionFilter = false;
      break;

    case 'A':
      // A类：标准用户（A + B）
      accessCondition = "`共享类型` IN ('A类', 'B类')";
      accessDescription = "当前为【A类用户】，仅可访问 `共享类型` 为 'A类' 或 'B类' 的资源。";
      needsPermissionFilter = true;
      break;

    case 'B':
    case 'D':
      // B类（普通） & D类（游客）：仅 B类
      const typeName = userType === 'D' ? "游客" : "普通用户";
      accessCondition = "`共享类型` = 'B类'";
      accessDescription = `⚠️ [${userType}类用户 - ${typeName}] 严格限制：仅可访问 \`共享类型\` 为 'B类' 的公开资源。`;
      needsPermissionFilter = true;
      break;

    default:
      // 兜底逻辑：默认为 B类（安全起见，未知类型按最低权限处理）
      accessCondition = "`共享类型` = 'B类'";
      accessDescription = "用户类型未知，系统强制按【B类】最低权限处理。";
      needsPermissionFilter = true;
  }
}

// ========================
// 3. 构造 System Prompt 中的权限指令
// ========================
let accessRuleNote = "";

if (needsPermissionFilter) {
  // 需要限制权限
  accessRuleNote = `
⛔ [权限硬性规则]
你必须在生成的 SQL WHERE 子句中加入以下强制条件：
>>> (${accessCondition}) <<<
注意：此条件必须作为基础准入条件，若不满足则直接排除。
`;
} else {
  // 不需要限制权限（商业版 或 C类）
  accessRuleNote = `
✅ [权限开放模式]
当前环境或用户拥有全量权限，请 **忽略** “共享类型”字段的限制，无需添加该字段的过滤条件。
`;
}

// ========================
// 4. 构造 User Prompt
// ========================
const userPrompt = `
【任务上下文】
- 用户提示：${prompt}
- 作物类别：${crop}
- 数据表名：${datatable}
- 用户身份：${userType}类
- 权限状态：${accessDescription}

【字段元数据】
${fieldList}

【查询建议】
${suggestion}
`.trim();

// ========================
// 5. 构造 System Prompt
// ========================
const systemPrompt = `
你是一个经验丰富的 MySQL 数据库专家，擅长基于用户意图自动生成符合 MYSQL 规范的 SQL 查询语句。
任务目标：查询表 \`${datatable}\`，从 \`${crop}\` 种质资源数据库中挖掘出最优资源。
【你的任务】
1. 请根据用户输入的任务，匹配表中字段，生成一条合法、可执行、具评分逻辑的 SQL 查询语句。
2. 在输出 SQL 之前，请先用一句话（不超过 30 个字）结合用户任务简述筛选资源的逻辑思考（不涉及具体数值，不要说共享资源权限A/B）。以“CropMonster将/CropMonster认为/CropMonster”开头，比如说：“CropMonster将优先选择高蛋白、高沉淀值、适宜硬度的品种，兼顾千粒重与穗粒数以提升产量潜力。”
### 🔒 权限控制（最高优先级）
${accessRuleNote}

### 🛠️ SQL 编写核心要求
1. **字段规范**：
   - 必须包含 \`全国统一编号\` 和 \`种质名称\` 字段。
   - 严格匹配元数据中的真实字段名，禁止虚构。
   - 遵守字段数据类型（如 varchar, decimal, tinyint）。
2. **语法禁忌**：
   - ❌ 禁止使用 REGEXP、TRIM、NULLIF 等非标准或低效函数。
   - ❌ 禁止使用 IF ... THEN ... 语法，逻辑判断请使用标准 \`IF(expr, val1, val2)\` 函数。
3. **业务逻辑**：
   - 不要添加与用户任务无关的查询条件。
   - 充分参考【附加规则】和【查询建议】。

### 📊 数量控制规范
- 若用户未提及具体数量，**默认使用 LIMIT 5**。
- 若用户提到具体数量（如“找一个”、“推荐三个”），请提取数字并设置 LIMIT（最多不超过 8）。
- 若数量表达模糊，仍兜底使用 LIMIT 5。

### 📝 附加业务规则
${extraRules}

### 📤 最终输出要求
请按以下格式严格输出，不要包含任何多余的解释文字：

1. **筛选逻辑简述**：[此处填入您结合用户任务的分析及筛选思考，基于关键词分析，不要出现无关字段或间接影响字段的分析，不要出现“评分”、“分数”、"B类权限"、"A类权限"等字眼，严禁超过 30 个字，不出现具体数值]
2. **SQL 语句**：[此处输出生成的合法 SQL 语句]
`;

// ========================
// 6. 输出结果
// ========================
return {
  json: {
    user_demo_session: userPrompt,
    system_prompt: systemPrompt,
    // 调试辅助信息
    meta: {
      userType,
      isCommercialMode,
      needsPermissionFilter,
      accessCondition
    }
  }
};

