        "株高", "穗长", "有效穗数", "穗粒数", "结实率", "千粒重", "粒宽", "剑叶长", "剑叶宽"
    ],
    bus_rice_data: [
        "株高", "穗长", "有效穗数", "穗粒数", "结实率", "千粒重", "粒长"
    ],
    corn_data: [
        "播种至出苗日数", "株高", "穗位高", "主茎叶片数", "生育日数", "穗长", "穗粗",
        "千粒重", "粗脂肪", "粗蛋白", "粗总淀粉", "赖氨酸"
    ],
    millet_data: [
        "分蘖数", "一株茎数", "主穗长度", "主茎长度", "主茎直径", "主茎节数",
        "单株秆重", "单株穗重", "单株粒重", "千粒重", "粗蛋白", "粗脂肪", "赖氨占蛋白"
    ],
    barley_data: [
        "株高(cm)", "单株穗数", "茎秆直径(mm)", "叶长(cm)", "叶宽(cm)", "穗长(cm)",
        "小穗数", "穗粒数", "千粒重(g)", "总淀粉", "粗蛋白", "赖氨酸", "赤霉病穗率",
        "赤霉病指数", "黄花发病率", "条纹病病率", "黄矮严重度", "黄花黄化度"
    ],
    sorghum_data: [
        "株高", "茎粗", "穗长", "穗柄长", "穗粒重", "千粒重", "着壳率", "角质率", "锤度",
        "粗蛋白", "赖氨占样品", "赖氨占蛋白", "单宁", "水份", "总淀粉", "直链淀粉", "支链淀粉"
    ],
    oats_data: [
        "株高", "穗长", "单株粒重", "主穗粒重", "千粒重", "有效分蘖", "轮层数"
    ],
    castor_data: [
        "生育期", "株高", "有效分枝数", "有效穗数", "果穗长度", "百粒重", "出仁率",
        "子实含油率", "子仁含油率"
    ],
    buckwheat_data: [
        "株高", "主茎节数", "主茎分枝数", "生育日数", "单株粒重", "千粒重"
    ],
    proso_data: [
        "株高", "主穗长", "主茎节数", "单株粒重", "千粒重", "生育日数", "粗蛋白", "粗脂肪", "赖氨酸"
    ],
    rapeseed_data: [
        "生育日数", "株高", "分枝高度", "全株角果数", "一次分枝数", "每果粒数", "千粒重",
        "含油率", "硫甙含量", "棕榈酸含量", "硬脂酸含量", "油酸含量", "亚油酸含量",
        "亚麻酸含量", "花生烯酸含量", "芥酸含量"
    ],
    soybean_data: [
        "生育日数", "百粒重", "株高", "粗蛋白", "粗脂肪"
    ]
};

// 获取当前作物对应的合法字段列表
const validFields = fieldMap[dataTypeKey] || fieldMap.wheat_data;
console.log(`Using data type: ${dataTypeKey}, ${validFields.length} valid fields`);

// 1.3 解析 LLM 输出（ideal_ranges, title）
let llmMeta = { title: "数据分析", ideal_ranges: {} };
try {
    const rawOutput = $input.first().json;
    const possibleFields = ['output', 'text', 'result', 'response'];
    let llmOutputRaw = '';
    for (const field of possibleFields) {
        if (typeof rawOutput[field] === 'string') {
            llmOutputRaw = rawOutput[field];
            break;
        }
    }
    if (!llmOutputRaw) throw new Error("No LLM output string found");

    const cleanJsonStr = llmOutputRaw
        .trim()
        .replace(/^```(?:json)?\s*/, '')
        .replace(/```+$/, '')
        .trim();

    const parsed = JSON.parse(cleanJsonStr);

    // 清洗 ideal_ranges：只保留 validFields 中的字段（允许 null）
    const filteredIdealRanges = {};
    if (parsed.ideal_ranges && typeof parsed.ideal_ranges === 'object') {
        Object.keys(parsed.ideal_ranges)
            .filter(key => validFields.includes(key))
            .forEach(key => {
                const range = parsed.ideal_ranges[key];
                if (Array.isArray(range)) {
                    filteredIdealRanges[key] = range; // 允许 [10, null] 或 [null, 20]
                }
            });
    }

    llmMeta = {
        title: parsed.title || `【${dataTypeKey.replace('_data', '')}】分析`,
        ideal_ranges: filteredIdealRanges
    };

} catch (e) {
    console.warn("LLM meta parse failed, using defaults:", e.message);
    llmMeta = {
        title: `【${dataTypeKey.replace('_data', '')}】分析`,
        ideal_ranges: {}
    };
}

// 如果没有原始数据，返回空配置
if (rawResources.length === 0) {
    return {
        json: {
            graphConfig: null
        }
    };
}

// ============================================================
// 2. 统计字段缺失率（在清洗前！）
// ============================================================
const completeness = {}; // 字段 → 有效数值比例

validFields.forEach(key => {
    let validCount = 0;
    let totalCount = 0;

    for (const item of rawResources) {
        if (!item || typeof item !== 'object') continue;
        if (!(key in item)) continue;

        const val = item[key];
        totalCount++;

        // 判断是否为有效数值
        if (val == null) {
            continue;
        } else if (typeof val === 'number' && !isNaN(val)) {
            validCount++;
        } else if (typeof val === 'string') {
            const num = parseFloat(val.replace(/[^-\d.]/g, ''));
            if (!isNaN(num)) {
                validCount++;
            }
        }
    }

    completeness[key] = totalCount > 0 ? validCount / totalCount : 0;
});

// ============================================================
// 3. 数据清洗（提取数值）
// ============================================================
const cleanedResources = rawResources
    .filter(item => item && typeof item === 'object')
    .map(item => {
        const newItem = { ...item };
        for (const key in newItem) {
            let val = newItem[key];

            if (val == null) {
                newItem[key] = 0;
                continue;
            }

            if (typeof val === 'string') {
                const match = val.match(/-?\d+(?:\.\d+)?/);
                if (match) {
                    const num = parseFloat(match[0]);
                    if (!isNaN(num)) {
                        newItem[key] = num;
                    } else {
                        newItem[key] = 0;
                    }
                } else {
                    newItem[key] = 0;
                }
            }
        }
        return newItem;
    });

// ============================================================
// 4. 字段筛选：仅保留 validFields 中且缺失率 <20% 的字段
// ============================================================
const selectedKeys = validFields
    .filter(key => completeness[key] > 0.8)  // 真实缺失率控制
    .filter(key => {
        // 确保该字段在 cleanedResources 中至少有一个非零值（避免全0字段）
        const values = cleanedResources.map(r => r[key]).filter(v => typeof v === 'number' && !isNaN(v));
        return values.length > 0 && Math.max(...values) > 0;
    })
    .slice(0, 5); // 最多 5 个

if (selectedKeys.length === 0) {
    return {
        json: {
            graphConfig: null
        }
    };
}

// ============================================================
// 5. 图表类型决策
// ============================================================
const rowsCnt = cleanedResources.length;
const colsCnt = selectedKeys.length;
let chartType = "bar";

if (colsCnt >= 3 && rowsCnt > 3) {
    chartType = "parallel";
} else if (colsCnt >= 3 && rowsCnt <= 3) {
    chartType = "radar";
} else {
    chartType = "bar";
}

// ============================================================
// 6. 构建 dimensions（坐标轴配置）
// ============================================================
const dimensions = selectedKeys.map(key => {
    const colValues = cleanedResources.map(r => r[key]);
    const dataMax = Math.max(...colValues);

    const dim = {
        dataKey: key,
        label: key,
        min: 0,
        max: Math.ceil(dataMax * 1.1),
        axisDirection: /病|倒伏|发病率|病率|指数|受害|率$/.test(key) ? "inverted" : "normal"
    };

    // === 关键：即使 idealMin/idealMax 为 null 也要显示字段 ===
    const idealRange = llmMeta.ideal_ranges[key];
    if (Array.isArray(idealRange)) {
        dim.idealMin = idealRange[0]; // 允许 null
        dim.idealMax = idealRange[1]; // 允许 null
    }

    return dim;
});

// ============================================================
// 7. 返回结果（不包含 cropDataKey）
// ============================================================
return {
    json: {
        graphConfig: {
            chartType,
            title: llmMeta.title,
            dimensions
        }
    }
};

// 1. 获取上游动态注入的变量
// 注意：这里的节点名称需要和你的 n8n 画布里完全一致
const contextPrompt = $('拼接上下文').last().json.prompt || "";
const uniqueSqls = $('去重query_hash').item.json.unique_sqls || "";
const sqlCount = $('去重query_hash').item.json.sql_count || 0;

// 2. 完整复刻大模型接收到的输入文本 (System + User)
// 这里的文本就是你提供给我的系统提示词和用户提示词的组合
const fullInputText = `
你是一个经验丰富的数据库专家和农学顾问，擅长将自然语言查询任务转化为精准、高效且合理的 SQL 语句。你需要结合用户的任务，对${sqlCount}个由智能体基于同一问题生成的 SQL 语句进行客观比较打分。

请你逐条评估这些 SQL 语句是否符合以下标准，并给出评分（0~100，分数越高表示越合理）：
1.是否能准确反映用户任务中的需求和限制条件；
