// 4. 定义一个针对“中文+SQL代码”混合场景的 Token 估算函数
// 优化后的 Token 估算函数
function estimateTokens(text) {
  if (!text) return 0;

  const chineseChars = text.match(/[\u4e00-\u9fa5]/g) || [];
  const englishWords = text.match(/[a-zA-Z]+/g) || [];
  const numbers = text.match(/[0-9]+/g) || [];
  // 匹配符号（排除中英文、数字、空格）
  const symbols = text.match(/[^\u4e00-\u9fa5a-zA-Z0-9\s]/g) || [];
  // 匹配空白符
  const whitespaces = text.match(/\s/g) || [];

  // 🎯 基于你的真实总耗 (5842) 进行的居中校准：
  const tokenCount = 
    (chineseChars.length * 1.0) +    // 中文回落到 1.0（大部分现代大模型的平均水平）
    (englishWords.length * 1.25) +   // 英文单词微调到 1.25
    (numbers.length * 1.0) +         // 数字保持 1.0
    (symbols.length * 0.5) +         // 【关键修正】符号降到 0.5，模拟分词器对 JSON/SQL 符号的合并压缩
    (whitespaces.length * 0.05);     // 【关键修正】大幅压缩空格权重，仅保留极小损耗

  return Math.round(tokenCount);
}

// 5. 分别计算输入、输出和总消耗
const inputTokens = estimateTokens(fullInputText);
const outputTokens = estimateTokens(outputText);
const totalTokens = inputTokens + outputTokens;

// 6. 返回结果：保留 Agent 原本的输出，并附加模拟的 Token 数据
return {
  ...$input.item.json,
  simulated_usage: {
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    total_tokens: totalTokens
  }
};

